st_batch_metrics_impl.installed:
function (os, app_list, metrics = c("revenue", "downloads"), 
    date_range = list(start_date = Sys.Date() - 90, end_date = Sys.Date() - 
        1), countries, granularity, parallel = FALSE, cache_dir = NULL, 
    verbose = TRUE, auth_token = Sys.getenv("SENSORTOWER_AUTH_TOKEN"), 
    max_cores = 2, max_concurrent_requests = 2, retry = TRUE, 
    max_retries = 3, publisher_ids = NULL) 
{
    if (missing(os) || is.null(os) || !os %in% c("ios", "android", 
        "unified")) {
        rlang::abort("'os' parameter is required and must be one of: 'ios', 'android', or 'unified'")
    }
    auth_token_val <- resolve_auth_token(auth_token, error_message = "Authentication token is required. Set SENSORTOWER_AUTH_TOKEN environment variable.")
    if (missing(countries) || is.null(countries)) {
        rlang::abort("'countries' parameter is required")
    }
    if (missing(granularity) || is.null(granularity)) {
        rlang::abort("'granularity' parameter is required. Specify one of: 'daily', 'weekly', 'monthly', 'quarterly'.")
    }
    if (identical(date_range, "ytd")) {
        rlang::abort("YTD mode is no longer supported in st_batch_metrics_impl. Please specify explicit start_date and end_date.")
    }
    if (!is.null(publisher_ids)) {
        return(fetch_publisher_batch(publisher_ids, os, metrics, 
            countries, date_range, granularity, auth_token_val, 
            verbose))
    }
    app_count <- if (is.data.frame(app_list)) 
        nrow(app_list)
    else length(app_list)
    if (verbose) 
        message("Processing ", app_count, " apps...")
    apps_df <- normalize_app_list(app_list, os, auth_token_val, 
        verbose)
    if (verbose) {
        message("Resolved apps:")
        message("  iOS apps: ", sum(!is.na(apps_df$ios_id)))
        message("  Android apps: ", sum(!is.na(apps_df$android_id)))
        message("  Unified only: ", sum(is.na(apps_df$ios_id) & 
            is.na(apps_df$android_id)))
    }
    fetch_groups <- group_apps_by_platform(apps_df)
    fetch_worker <- function(group, group_name) {
        if (verbose) 
            message("\nFetching metrics for ", group_name, " group (", 
                nrow(group), " apps)...")
        active_res <- fetch_active_users_batch(group, group_name, 
            metrics, countries, date_range, granularity, auth_token_val, 
            verbose)
        sales_res <- fetch_sales_batch(group, group_name, metrics, 
            countries, date_range, granularity, auth_token_val, 
            verbose, os)
        if (verbose) {
            if (!is.null(active_res) && nrow(active_res) > 0) {
                message("Active res app_id type: ", typeof(active_res$app_id), 
                  " class: ", class(active_res$app_id))
            }
            if (!is.null(sales_res) && nrow(sales_res) > 0) {
                message("Sales res app_id type: ", typeof(sales_res$app_id), 
                  " class: ", class(sales_res$app_id))
            }
        }
        if (!is.null(active_res) && nrow(active_res) > 0 && "app_id" %in% 
            names(active_res)) {
            active_res$app_id <- as.character(active_res$app_id)
        }
        if (!is.null(sales_res) && nrow(sales_res) > 0 && "app_id" %in% 
            names(sales_res)) {
            sales_res$app_id <- as.character(sales_res$app_id)
        }
        dplyr::bind_rows(active_res, sales_res)
    }
    results <- execute_batch_fetch(fetch_groups, fetch_worker, 
        parallel, max_cores, verbose)
    finalize_batch_results_internal(results, apps_df, os = os)
}

finalize_batch_results.installed:
function (results, apps_df, os = NULL) 
{
    finalize_batch_results_internal(results, apps_df, os = os)
}

fetch_active_users_batch.installed:
function (group, group_name, metrics, countries, date_range, 
    granularity, auth_token, verbose) 
{
    active_user_metrics <- intersect(metrics, c("dau", "wau", 
        "mau"))
    if (length(active_user_metrics) == 0) {
        return(tibble::tibble())
    }
    request_plan <- build_active_users_request_plan(group, group_name, 
        active_user_metrics)
    if (nrow(request_plan) == 0) {
        return(tibble::tibble())
    }
    if (verbose) {
        message("  Fetching active user metrics (platform endpoints)...")
    }
    default_time_period <- active_users_default_time_period(granularity)
    request_results <- purrr::pmap(.l = list(platform_os = request_plan$platform, 
        app_ids = request_plan$app_ids, metric_name = request_plan$metric), 
        .f = function(platform_os, app_ids, metric_name) {
            fetch_active_users_request(platform_os = platform_os, 
                app_ids = app_ids, metric_name = metric_name, 
                countries = countries, date_range = date_range, 
                default_time_period = default_time_period, auth_token = auth_token, 
                verbose = verbose)
        })
    platform_results <- dplyr::bind_rows(request_results)
    if (nrow(platform_results) == 0) {
        return(tibble::tibble())
    }
    if (group_name %in% c("ios", "android")) {
        return(platform_results %>% dplyr::mutate(entity_id = .data$app_id) %>% 
            dplyr::select(-"platform"))
    }
    if (group_name == "both") {
        pair_lookup <- dplyr::bind_rows(group %>% dplyr::transmute(platform = "ios", 
            app_id = as.character(.data$ios_id), entity_id = paste0(.data$ios_id, 
                "_", .data$android_id)), group %>% dplyr::transmute(platform = "android", 
            app_id = as.character(.data$android_id), entity_id = paste0(.data$ios_id, 
                "_", .data$android_id))) %>% dplyr::filter(!is.na(.data$app_id) & 
            nzchar(.data$app_id)) %>% dplyr::distinct(.data$platform, 
            .data$app_id, .data$entity_id)
        return(platform_results %>% dplyr::inner_join(pair_lookup, 
            by = c("platform", "app_id")) %>% dplyr::group_by(.data$entity_id, 
            .data$date, .data$country, .data$metric) %>% dplyr::summarise(value = sum(.data$value, 
            na.rm = TRUE), .groups = "drop") %>% dplyr::mutate(app_id = .data$entity_id) %>% 
            dplyr::select("app_id", "date", "country", "metric", 
                "value", "entity_id"))
    }
    tibble::tibble()
}

finalize_batch_results_internal.installed:
function (results, apps_df, os = NULL) 
{
    if (length(results) == 0) {
        return(tibble::tibble())
    }
    if (is.data.frame(results)) {
        results <- list(results)
    }
    results <- dplyr::bind_rows(results)
    if (nrow(results) == 0) {
        return(tibble::tibble())
    }
    results <- tibble::as_tibble(results)
    if (!"entity_id" %in% names(results)) {
        results$entity_id <- if ("app_id" %in% names(results)) 
            as.character(results$app_id)
        else NA_character_
    }
    if (!"app_id" %in% names(results)) {
        results$app_id <- as.character(results$entity_id)
    }
    missing_entity_id <- is.na(results$entity_id) | !nzchar(as.character(results$entity_id))
    results$entity_id[missing_entity_id] <- as.character(results$app_id[missing_entity_id])
    results$entity_id <- as.character(results$entity_id)
    lookup_df <- build_batch_id_lookup(apps_df)
    final_results <- results %>% dplyr::left_join(lookup_df, 
        by = "entity_id")
    if (nrow(final_results) > 0) {
        has_unified_id <- !is.na(final_results$unified_id) & 
            nzchar(final_results$unified_id)
        should_use_unified <- has_unified_id & (identical(os, 
            "unified") | final_results$lookup_app_id_type %in% 
            c("unified", "unified_pair"))
        fallback_id <- dplyr::coalesce(final_results$original_id, 
            final_results$entity_id, final_results$app_id)
        final_results$canonical_app_id <- ifelse(should_use_unified, 
            final_results$unified_id, fallback_id)
        final_results$app_id <- final_results$canonical_app_id
        final_results$app_id_type <- ifelse(should_use_unified, 
            "unified", detect_batch_app_id_type(final_results$app_id, 
                final_results$entity_id))
        cols_to_keep <- c("original_id", "app_name", "app_id", 
            "canonical_app_id", "entity_id", "platform_pair_id", 
            "app_id_type", "date", "country", "metric", "value")
        existing_cols <- intersect(cols_to_keep, names(final_results))
        final_results <- final_results[, existing_cols]
    }
    final_results
}

.st_metrics_normalize_output.installed:
function (data, requested_ids, requested_countries, os, metrics, 
    revenue_unit, shape) 
{
    if (is.null(data) || !nrow(data)) {
        return(if (shape == "long") {
            tibble::tibble(app_id = character(), os = character(), 
                country = character(), date = as.Date(character()), 
                metric = character(), value = numeric())
        } else {
            wide <- tibble::tibble(app_id = character(), os = character(), 
                country = character(), date = as.Date(character()))
            for (metric_name in metrics) {
                wide[[metric_name]] <- numeric()
            }
            wide
        })
    }
    if (all(c("metric", "value") %in% names(data))) {
        data_tbl <- tibble::as_tibble(data)
        if (!"original_id" %in% names(data_tbl)) {
            data_tbl$original_id <- NA_character_
        }
        if (!"app_id" %in% names(data_tbl)) {
            data_tbl$app_id <- NA_character_
        }
        if (!"app_id_type" %in% names(data_tbl)) {
            data_tbl$app_id_type <- NA_character_
        }
        has_canonical_unified <- !is.na(data_tbl$app_id_type) & 
            data_tbl$app_id_type == "unified" & !is.na(data_tbl$app_id) & 
            nzchar(as.character(data_tbl$app_id))
        data_tbl$.st_output_app_id <- ifelse(has_canonical_unified, 
            as.character(data_tbl$app_id), dplyr::coalesce(as.character(data_tbl$original_id), 
                as.character(data_tbl$app_id)))
        normalized_long <- data_tbl %>% dplyr::transmute(app_id = as.character(.data$.st_output_app_id), 
            os = os, country = as.character(.data$country), date = as.Date(.data$date), 
            metric = tolower(as.character(.data$metric)), value = as.numeric(.data$value)) %>% 
            dplyr::filter(.data$metric %in% metrics)
    }
    else {
        normalized_wide <- .st_metrics_coerce_wide(data = tibble::as_tibble(data), 
            requested_id = requested_ids[1], os = os)
        normalized_long <- normalized_wide %>% tidyr::pivot_longer(cols = dplyr::any_of(metrics), 
            names_to = "metric", values_to = "value")
    }
    if (!"WW" %in% requested_countries) {
        normalized_long <- normalized_long %>% dplyr::filter(.data$country %in% 
            requested_countries)
    }
    conflicts <- normalized_long %>% dplyr::distinct(.data$app_id, 
        .data$os, .data$country, .data$date, .data$metric, .data$value) %>% 
        dplyr::count(.data$app_id, .data$os, .data$country, .data$date, 
            .data$metric, name = "n_values") %>% dplyr::filter(.data$n_values > 
        1)
    if (nrow(conflicts) > 0) {
        rlang::abort(sprintf("st_metrics() returned conflicting duplicate metric values for app_id '%s', country '%s', date '%s', metric '%s'.", 
            conflicts$app_id[[1]], conflicts$country[[1]], format(conflicts$date[[1]], 
                "%Y-%m-%d"), conflicts$metric[[1]]))
    }
    normalized_long <- normalized_long %>% dplyr::distinct(.data$app_id, 
        .data$os, .data$country, .data$date, .data$metric, .data$value)
    if (revenue_unit == "cents") {
        revenue_rows <- normalized_long$metric == "revenue"
        normalized_long$value[revenue_rows] <- normalized_long$value[revenue_rows] * 
            100
    }
    normalized_long <- normalized_long %>% dplyr::arrange(.data$app_id, 
        .data$date, .data$country, .data$metric)
    if (shape == "long") {
        return(normalized_long)
    }
    wide <- normalized_long %>% tidyr::pivot_wider(names_from = "metric", 
        values_from = "value") %>% dplyr::select("app_id", "os", 
        "country", "date", dplyr::any_of(metrics))
    for (metric_name in setdiff(metrics, names(wide))) {
        wide[[metric_name]] <- numeric(nrow(wide))
    }
    wide <- wide %>% dplyr::select("app_id", "os", "country", 
        "date", dplyr::all_of(metrics)) %>% dplyr::arrange(.data$app_id, 
        .data$date, .data$country)
    wide
}
